#include <iostream>
#include <string>
#include <vector>

int main()
{
    int cap{};
    int m{};
    if (!(std::cin >> cap >> m)) return 0;

    std::vector<int> buf(static_cast<std::size_t>(cap < 0 ? 0 : cap), 0);
    std::size_t count{ 0 };

    for (int i = 0; i < m; ++i)
    {
        std::string cmd;
        if (!(std::cin >> cmd)) break;

        if (cmd == "push")
        {
            int x{};
            std::cin >> x;
            if (count == buf.size()) std::cout << "push full\n";
            else { buf[count] = x; ++count; std::cout << "push ok\n"; }
        }
        else if (cmd == "pop")
        {
            if (count == 0) std::cout << "pop empty\n";
            else { --count; std::cout << "pop " << buf[count] << "\n"; }
        }
        else if (cmd == "top")
        {
            if (count == 0) std::cout << "top empty\n";
            else std::cout << "top " << buf[count - 1] << "\n";
        }
        else if (cmd == "size")
        {
            std::cout << "size " << count << "\n";
        }
    }

    return 0;
}

