import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    pos = 0
    cap = int(data[pos]); pos += 1
    m = int(data[pos]); pos += 1

    buf = [0] * max(cap, 0)
    count = 0
    out = []

    for _ in range(m):
        if pos >= len(data):
            break
        cmd = data[pos]; pos += 1
        if cmd == "push":
            x = int(data[pos]); pos += 1
            if count == len(buf):
                out.append("push full")
            else:
                buf[count] = x
                count += 1
                out.append("push ok")
        elif cmd == "pop":
            if count == 0:
                out.append("pop empty")
            else:
                count -= 1
                out.append("pop %d" % buf[count])
        elif cmd == "top":
            out.append("top empty" if count == 0 else "top %d" % buf[count - 1])
        elif cmd == "size":
            out.append("size %d" % count)

    print("\n".join(out))

main()
